import hashlib

def measure(images,case):
    size=case['length']
    current=images[0].read(0,size)
    digest=hashlib.sha256(current).hexdigest()
    if len(current)==size and digest==case['sha256']:
        return dict(bytes=size,sha256=digest,skipped=True)
    pending=[]
    qd=case['queue_depth']
    def reap(index):
        completion,client=pending.pop(index)
        completion.wait_for_complete_and_cb()
        if completion.get_return_value()!=0:raise RuntimeError('native aio write failed')
        return client
    for index,operation in enumerate(case['operations']):
        client=index%len(images)
        while sum(c==client for _,c in pending)>=qd:
            reap(next(i for i,(_,c)in enumerate(pending)if c==client))
        completion=images[client].aio_write(operation['data'],operation['offset'],lambda done:None)
        pending.append((completion,client))
        if case['flush_each']:
            reap(len(pending)-1)
            images[client].flush()
    while pending:reap(0)
    for image in images:image.flush()
    actual=images[0].read(0,size)
    digest=hashlib.sha256(actual).hexdigest()
    assert len(actual)==size and digest==case['sha256'],'full actual final image SHA'
    return dict(bytes=len(actual),sha256=digest,skipped=False)

